// game.js - 拼豆配对 微信小游戏版

var _g = typeof GameGlobal !== 'undefined' ? GameGlobal : (typeof global !== 'undefined' ? global : (typeof window !== 'undefined' ? window : {}));
var GamePlatform = _g.GamePlatform;

// requestAnimationFrame polyfill (browser + mini-game)
var _raf = typeof requestAnimationFrame !== 'undefined' ? requestAnimationFrame :
  typeof wx !== 'undefined' ? wx.requestAnimationFrame :
  typeof tt !== 'undefined' ? tt.requestAnimationFrame :
  function(cb) { return setTimeout(function() { cb(Date.now()); }, 16); };
var _caf = typeof cancelAnimationFrame !== 'undefined' ? cancelAnimationFrame :
  typeof wx !== 'undefined' ? wx.cancelAnimationFrame :
  typeof tt !== 'undefined' ? tt.cancelAnimationFrame :
  function(id) { clearTimeout(id); };

var canvas = GamePlatform.createCanvas()

var ctx = canvas.getContext('2d')

var sys = GamePlatform.getSystemInfoSync()

var W = sys.windowWidth

var H = sys.windowHeight

canvas.width = W

canvas.height = H

// Fill background

ctx.fillStyle = '#f0f0f8';

ctx.fillRect(0, 0, canvas.width, canvas.height);

var SAFE_TOP = (sys.safeArea && sys.safeArea.top) || 0
var SAFE_BOTTOM = (sys.safeArea && sys.safeArea.bottom) || H

function roundRect(ctx, x, y, w, h, r) {

  r = Math.min(r || 0, w/2, h/2);

  ctx.beginPath();

  ctx.moveTo(x + r, y);

  ctx.lineTo(x + w - r, y);

  ctx.quadraticCurveTo(x + w, y, x + w, y + r);

  ctx.lineTo(x + w, y + h - r);

  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);

  ctx.lineTo(x + r, y + h);

  ctx.quadraticCurveTo(x, y + h, x, y + h - r);

  ctx.lineTo(x, y + r);

  ctx.quadraticCurveTo(x, y, x + r, y);

  ctx.closePath();

}

function hexA(hex, a) {
  var h = String(hex || "").replace("#", "")
  if (h.length === 3) h = h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2)
  var r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16)
  if (isNaN(r) || isNaN(g) || isNaN(b)) return hex
  return "rgba(" + r + "," + g + "," + b + "," + a + ")"
}

