// Animation system

var animBatch = null

var animTimer = null
var _animGeneration = 0

function cancelAnimation() {
  if (animTimer) {
    _caf(animTimer);
    animTimer = null;
  }
  animBatch = null;
}

var ANIM_DURATION = GamePlatform._ANIM_DURATION || 600 // ms

function easeOutQuad(t) { return t * (2 - t) }

function startAnimBatch(batch, callback) {

  // Cancel any previous animation
  cancelAnimation();

  // Add stagger delay for each block (60ms apart)

  for (var si = 0; si < batch.length; si++) {

    batch[si].stagger = si * (GamePlatform._STAGGER_BASE || 80)

  }

  var totalDur = ANIM_DURATION + (batch.length - 1) * 60

  animBatch = { batch: batch, progress: 0, totalDur: totalDur, callback: callback || function(){} }

  var gen = ++_animGeneration;
  var startTime = Date.now();
  function animTick() {
    if (_animGeneration !== gen) return;
    var elapsed = Date.now() - startTime;
    animBatch.progress = Math.min(1, elapsed / animBatch.totalDur)
    draw()
    if (animBatch.progress >= 1) {
      _caf(animTimer)
      animTimer = null
      var cb = animBatch.callback
      animBatch = null
      _animGeneration++;
      cb()
      draw()
    } else {
      animTimer = _raf(animTick)
    }
  }
  animTimer = _raf(animTick)

}

function isAnimatingFrom(type, r, c) {

  if (!animBatch) return false

  for (var i = 0; i < animBatch.batch.length; i++) {

    var m = animBatch.batch[i]

    if (m.fromType === type && m.fr === r && m.fc === c) return true

  }

  return false

}

function getCenter(type, r, c) {

  if (type === 'board') {

    var bx = PAD + c * CELL + CELL/2
    var by = CY + TOP_OFFSET + r * CELL + CELL/2
    var cx = PAD + BOARD_SIZE / 2
    var cy = CY + TOP_OFFSET + BOARD_SIZE / 2
    return {
      x: (bx - cx) * zoom + panX + cx,
      y: (by - cy) * zoom + panY + cy
    }

  } else {

    return { x: PAD + c * SLOT_CELL + SLOT_CELL/2, y: SLOT_TOP + r * (SLOT_CELL + 3) + SLOT_CELL/2 }

  }

}

