function drawOpenBook(cx, cy, w, h) {
  if (typeof homeBookImage !== "undefined" && homeBookImage.loaded && homeBookImage.img) {
    // Draw the uploaded open-book illustration (square 1179x1179) centered so the
    // book art sits in the same area as the previous hand-drawn book.
    var side = w
    ctx.drawImage(homeBookImage.img, cx - side * 0.54, cy - side * 0.51, side, side)
    return
  }

  var half = w / 2

  var spine = 14

  var pageW = (w - spine) / 2

  var pageH = h

  var tilt = 0.12

  ctx.save()

  ctx.shadowColor = "rgba(120,90,180,0.35)"

  ctx.shadowBlur = 24

  ctx.shadowOffsetY = 9

  ctx.save()

  ctx.translate(cx - spine / 2, cy)

  ctx.rotate(tilt)

  ctx.fillStyle = "#FFFDF4"

  ctx.beginPath()

  roundRect(ctx, -pageW, -pageH / 2, pageW, pageH, 10)

  ctx.fill()

  ctx.restore()

  ctx.save()

  ctx.translate(cx + spine / 2, cy)

  ctx.rotate(-tilt)

  ctx.fillStyle = "#FFFDF4"

  ctx.beginPath()

  roundRect(ctx, 0, -pageH / 2, pageW, pageH, 10)

  ctx.fill()

  ctx.restore()

  ctx.restore()

  ctx.strokeStyle = "#E3D7F4"

  ctx.lineWidth = 1.5

  ctx.save()

  ctx.translate(cx - spine / 2, cy)

  ctx.rotate(tilt)

  ctx.beginPath()

  roundRect(ctx, -pageW, -pageH / 2, pageW, pageH, 10)

  ctx.stroke()

  ctx.restore()

  ctx.save()

  ctx.translate(cx + spine / 2, cy)

  ctx.rotate(-tilt)

  ctx.beginPath()

  roundRect(ctx, 0, -pageH / 2, pageW, pageH, 10)

  ctx.stroke()

  ctx.restore()

  ctx.fillStyle = "#C9B4EE"

  ctx.beginPath()

  roundRect(ctx, cx - spine / 2, cy - pageH / 2 + 4, spine, pageH - 8, 5)

  ctx.fill()

  ctx.fillStyle = "rgba(255,255,255,0.35)"

  ctx.beginPath()

  roundRect(ctx, cx - spine / 2 + 3, cy - pageH / 2 + 10, 3, pageH - 20, 2)

  ctx.fill()

  ctx.strokeStyle = "rgba(200,190,225,0.7)"

  ctx.lineWidth = 1.2

  ctx.beginPath()

  ctx.moveTo(cx - spine / 2 - 1.5, cy - pageH / 2 + 10)

  ctx.lineTo(cx - spine / 2 - 1.5, cy + pageH / 2 - 10)

  ctx.moveTo(cx + spine / 2 + 1.5, cy - pageH / 2 + 10)

  ctx.lineTo(cx + spine / 2 + 1.5, cy + pageH / 2 - 10)

  ctx.stroke()

  ctx.strokeStyle = "rgba(200,190,225,0.55)"

  ctx.lineWidth = 1.4

  ctx.save()

  ctx.translate(cx - spine / 2, cy)

  ctx.rotate(tilt)

  for (var i = 0; i < 3; i++) {

    var ly = pageH / 2 - 15 - i * 12

    ctx.beginPath()

    ctx.moveTo(-pageW + 12, ly)

    ctx.lineTo(-pageW * 0.5, ly)

    ctx.stroke()

  }

  ctx.restore()

  ctx.save()

  ctx.translate(cx + spine / 2, cy)

  ctx.rotate(-tilt)

  for (var j = 0; j < 3; j++) {

    var ry = pageH / 2 - 15 - j * 12

    ctx.beginPath()

    ctx.moveTo(pageW * 0.5, ry)

    ctx.lineTo(pageW - 12, ry)

    ctx.stroke()

  }

  ctx.restore()

}


