      var to = getCenter(m.toType, m.tr, m.tc)

      // High arc trajectory

      var arcH = Math.sin(pp * Math.PI) * 80

      var cx2 = from.x + (to.x - from.x) * pp

      var cy2 = from.y + (to.y - from.y) * pp - arcH

      // Dramatic scale: shrink then expand

      var fromSize = (m.fromType === 'board') ? CELL * 0.7 : SLOT_CELL * 0.7
      var toSize = (m.toType === 'board') ? CELL * 0.7 : SLOT_CELL * 0.7
      var baseS = fromSize + (toSize - fromSize) * pp

